import java.io.*; import java.util.*; import java.util.stream.*; import static java.util.stream.Collectors.toList; class Result { public static int equal(List<Integer> arr) { int minVal = Collections.min(arr); int minOps = Integer.MAX_VALUE; for (int i = 0; i <= 4; i++) { int currentTarget = minVal - i; int totalOps = 0; for (int val : arr) { int diff = val - currentTarget; totalOps += (diff / 5) + ((diff % 5) / 2) + (((diff % 5) % 2) / 1); } minOps = Math.min(minOps, totalOps); } return minOps; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH"))); int t = Integer.parseInt(bufferedReader.readLine().trim()); IntStream.range(0, t).forEach(tItr -> { try { int n = Integer.parseInt(bufferedReader.readLine().trim()); List<Integer> arr = Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(toList()); int result = Result.equal(arr); bufferedWriter.write(String.valueOf(result)); bufferedWriter.newLine(); } catch (IOException ex) { throw new RuntimeException(ex); } }); bufferedReader.close(); bufferedWriter.close(); } }